import { shouldRetry, backoff } from './retry';

export async function call(fn: () => Promise<void>, max = 3) {
  for (let a = 0; ; a++) {
    try { return await fn(); } catch (e) {
      if (!shouldRetry(a, max)) throw e;
      await new Promise((r) => setTimeout(r, backoff(a)));
    }
  }
}

